:2011,"fund_name":null,"source_url":"https://www.generalatlantic.com/investments/?status=Past","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Patni","slug":"patni","domain":"capgemini.com","description":"Patni Computer Systems was a global provider of strategic IT consulting and implementation services.","sector":"Technology","hq":"India","status":"realized","invested_year":2002,"exit_year":2011,"fund_name":null,"source_url":"https://www.generalatlantic.com/investments/?status=Past","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Critical Path","slug":"critical-path","domain":"synchronoss.com","description":"Critical Path was a global provider of messaging solutions.","sector":"Technology","hq":"EMEA","status":"realized","invested_year":2001,"exit_year":2013,"fund_name":null,"source_url":"https://www.generalatlantic.com/investments/?status=Past","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Phonetic Systems","slug":"phonetic-systems","domain":"nuance.com","description":"Phonetic Systems was a global provider of voice and language solutions for businesses and consumers.","sector":"Technology","hq":"United States","status":"realized","invested_year":2001,"exit_year":2012,"fund_name":null,"source_url":"https://www.generalatlantic.com/investments/?status=Past","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"ProPay","slug":"propay","domain":"propay.com.br","description":"Acquired by TSYS, ProPay is a provider of payment processing solutions serving a variety of business needs.","sector":"Technology","hq":"Latin America","status":"realized","invested_year":2000,"exit_year":2010,"fund_name":null,"source_url":"https://www.generalatlantic.com/investments/?status=Past","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"IPValue","slug":"ipvalue","domain":"ipvalue.com","description":"IPValue is a provider of intellectual property transaction and advisory services.","sector":"Technology","hq":"United States","status":"realized","invested_year":2000,"exit_year":2014,"fund_name":null,"source_url":"https://www.generalatlantic.com/investments/?status=Past","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Chess.com","slug":"chess-com","domain":"chess.com","description":"Chess.com is an online destination for playing, learning and watching Chess.","sector":"Technology","hq":"United States","status":"current","invested_year":2021,"exit_year":null,"fund_name":null,"source_url":"https://www.generalatlantic.com/investments/?status=Current","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Fluency Academy","slug":"fluency-academy","domain":"fluencytv.com","description":"Fluency Academy is an online language learning platform in Brazil.","sector":"Technology","hq":"Latin America","status":"current","invested_year":2021,"exit_year":null,"fund_name":null,"source_url":"https://www.generalatlantic.com/investments/?status=Current","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Certinia","slug":"certinia","domain":"certinia.com","description":"Certinia is a cloud-based services-as-a-business platform.","sector":"Technology","hq":"United States","status":"current","invested_year":2023,"exit_year":null,"fund_name":null,"source_url":"https://www.generalatlantic.com/investments/?status=Current","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Chime","slug":"chime","domain":"chimebank.com","description":"Chime is a digital consumer banking provider.","sector":"Financial Services","hq":"United States","status":"current","invested_year":2019,"exit_year":null,"fund_name":null,"source_url":"https://www.generalatlantic.com/investments/?status=Current","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null}],"deals":[]}$pf$::jsonb;
  n_companies int;
  n_deals int;
begin
  select id into gp from public.companies
   where category = 'GP' and name = 'General Atlantic'
   order by (source = 'master_directory') desc nulls last, created_at
   limit 1;
  if gp is null then raise exception 'sponsor % is not in the directory', 'General Atlantic'; end if;

  insert into public.portfolio_companies as pc (external_key, gp_company_id, name, domain, description, sector, hq, status, invested_year, exit_year, fund_name,
      source, source_url, deal_value, deal_currency, deal_value_basis, stake_pct, co_investors, deal_source_url, researched_at)
  select gp::text || ':' || (c->>'slug'), gp, c->>'name', c->>'domain', c->>'description', c->>'sector', c->>'hq', c->>'status',
         (c->>'invested_year')::int, (c->>'exit_year')::int, c->>'fund_name', 'web_research', c->>'source_url',
         (c->>'deal_value')::numeric, c->>'deal_currency', c->>'deal_value_basis', (c->>'stake_pct')::numeric,
         coalesce(array(select jsonb_array_elements_text(c->'co_investors')), '{}'), c->>'deal_source_url', now()
    from jsonb_array_elements(doc->'companies') c
  on conflict (external_key) do update set
    name = case when pc.source = 'manual' then pc.name else excluded.name end,
    domain = coalesce(pc.domain, excluded.domain),
    description = case when pc.source = 'manual' then coalesce(pc.description, excluded.description) else coalesce(excluded.description, pc.description) end,
    sector = case when pc.source = 'manual' then coalesce(pc.sector, excluded.sector) else coalesce(excluded.sector, pc.sector) end,
    hq = case when pc.source = 'manual' then coalesce(pc.hq, excluded.hq) else coalesce(excluded.hq, pc.hq) end,
    status = coalesce(excluded.status, pc.status),
    invested_year = coalesce(excluded.invested_year, pc.invested_year),
    exit_year = coalesce(excluded.exit_year, pc.exit_year),
    fund_name = coalesce(excluded.fund_name, pc.fund_name),
    source_url = case when pc.source = 'manual' then coalesce(pc.source_url, excluded.source_url) else excluded.source_url end,
    deal_value = coalesce(excluded.deal_value, pc.deal_value),
    deal_currency = case when excluded.deal_value is not null then excluded.deal_currency else pc.deal_currency end,
    deal_value_basis = case when excluded.deal_value is not null then excluded.deal_value_basis else pc.deal_value_basis end,
    stake_pct = coalesce(excluded.stake_pct, pc.stake_pct),
    co_investors = case when cardinality(excluded.co_investors) > 0 then excluded.co_investors else pc.co_investors end,
    deal_source_url = coalesce(excluded.deal_source_url, pc.deal_source_url),
    researched_at = now();
  get diagnostics n_companies = row_count;

  insert into public.deals as d (external_key, date, date_text, kind, asset_class, target, target_kind, target_key, target_website, investor, investor_company_id,
      co_investors, seller, round, stake_pct, amount, currency, amount_basis, valuation, valuation_currency, headline, summary, source_name, source_url,
      evidence, verified, source)
  select x->>'key', (x->>'date')::date, x->>'date_text', x->>'kind', x->>'asset_class', x->>'target', 'company',
         public.borrower_key(coalesce(x->>'portco_name', x->>'target')), x->>'target_website', x->>'investor',
         case when (x->>'sponsor_is_investor')::boolean then gp else (select m.company_id from ingest.match_firm(x->>'investor', array['GP']) m) end,
         coalesce(array(select jsonb_array_elements_text(x->'co_investors')), '{}'), x->>'seller', x->>'round', (x->>'stake_pct')::numeric,
         (x->>'amount')::numeric, x->>'currency', x->>'amount_basis', (x->>'valuation')::numeric, x->>'valuation_currency',
         x->>'headline', x->>'summary', x->>'source_name', x->>'source_url', x->>'evidence', (x->>'verified')::boolean, 'web_research'
    from jsonb_array_elements(doc->'deals') x
  on conflict (external_key) do update set
    date = excluded.date, date_text = excluded.date_text, kind = excluded.kind, target = excluded.target, target_key = excluded.target_key,
    target_website = coalesce(excluded.target_website, d.target_website), investor = excluded.investor,
    investor_company_id = coalesce(excluded.investor_company_id, d.investor_company_id),
    co_investors = (select coalesce(array_agg(distinct v), '{}') from unnest(d.co_investors || excluded.co_investors) v),
    seller = coalesce(excluded.seller, d.seller), round = coalesce(excluded.round, d.round), stake_pct = coalesce(excluded.stake_pct, d.stake_pct),
    amount = excluded.amount, currency = excluded.currency, amount_basis = excluded.amount_basis,
    valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, headline = excluded.headline,
    summary = coalesce(excluded.summary, d.summary), source_name = excluded.source_name, source_url = excluded.source_url,
    evidence = excluded.evidence, verified = coalesce(excluded.verified, d.verified);
  get diagnostics n_deals = row_count;

  update public.companies set portfolio_note = 'generalatlantic.com/investments/ server-rendered list paginated via ?status=Current|Past&pg=N (406 items, cross-checked against WP REST /wp-json/wp/v2/investment X-WP-Total=406); hq = the list''s Region column; Infrastructure filter defers to Actis (act.is), not included', portfolio_researched_at = now() where id = gp;
  insert into ingest.log (what, detail) values ('load_portfolio', jsonb_build_object('sponsor', 'General Atlantic', 'companies', n_companies, 'deals', n_deals));
end $pfdo$;
